-- Reproducible 2026 youth-programme catalogue refresh.
-- This migration updates current official eligibility/verification notes and adds the separate UzVC startup investment path.
insert into public.youth_opportunity_programs (slug, title, provider, category, summary, benefit, age_min, age_max, audience_tags, eligibility, steps, documents, application_channel, application_url, source_title, source_url, secondary_source_url, deadline_note, status_note, verified_on, active, featured, sort_order)
values
('yoshlar-daftari', '“Yoshlar daftari” — maqsadli ijtimoiy yordam', 'Yoshlar ishlari agentligi · mahalla yettiligi', 'social_support', '14 yoshga to‘lgan va 30 yoshdan oshmagan (31 yoshga yetmagan), belgilangan ijtimoiy mezonlarga mos yoshlar uchun ijtimoiy yordamlar va individual ijtimoiy shartnoma tizimi.', 'Aniq yordam turi va shaxsiy holatga qarab ta’lim, kasb, ijtimoiy yoki boshqa qo‘llab-quvvatlash ko‘rsatilishi mumkin. Yoshlar daftari mukofot yoki pulni avtomatik bermaydi; yordam alohida mezon va qarorga bog‘liq.', 14, 30, array['14 yoshga to‘lgan va 30 yoshdan oshmagan yoshlar','Ijtimoiy reyestrga kiritilgan oilalar a’zolari','Oila a’zosi boshiga oylik daromadi minimal iste’mol xarajatlarining 2 baravaridan ko‘p bo‘lmagan oilalardagi yoshlar']::text[], '{"max_age":30,"min_age":14,"important":"Faqat ishsiz bo‘lish yoki o‘zini o‘zi band qilganlikning o‘zi Yoshlar daftariga kiritish uchun yetarli emas. Har bir yordam turiga qo‘shimcha shart qo‘llanishi mumkin.","incentive":"Kamida 6 oy shartnoma shartlarini a’lo bajargan eng yuqori natijali 1 000 nafargacha yoshga har yili dekabrda 3 BHM mukofoti berilishi mumkin; bu barcha arizachilarga kafolatlangan to‘lov emas.","residency":"Doimiy yoki vaqtincha yashash joyi bo‘yicha, yoxud amalda yashayotgan mahalla doirasida murojaat qilinadi.","main_criteria":"Ijtimoiy reyestrga kiritilgan oilaning a’zosi bo‘lish yoki oila a’zolarining har biriga to‘g‘ri keladigan oylik daromad minimal iste’mol xarajatlari miqdorining 2 baravaridan ko‘p bo‘lmasligi kerak.","social_contract":"Ayrim yordamlar individual reja va ijtimoiy shartnoma asosida beriladi; majburiyatlar bajarilishi elektron platformada oyma-oy 100 balli tizimda kuzatiladi."}'::jsonb, '["14 yoshga to‘lganingiz va 30 yoshdan oshmaganingizni tekshiring.","Oilangiz Ijtimoiy reyestrda borligini yoki oila a’zosi boshiga oylik daromad minimal iste’mol xarajatlarining 2 baravaridan oshmasligini aniqlang.","Qanday aniq yordam kerakligini tanlang. Daftarga kiritilishning o‘zi yordam ajratilishini bildirmaydi.","Doimiy/vaqtincha yashash joyingiz yoki amalda yashayotgan mahallangiz bo‘yicha Davlat xizmatlari markazi, my.gov.uz yoki Yoshlar yagona elektron platformasi orqali murojaat qiling.","Yoshlar yetakchisi murojaatni o‘rganib, mahalla yettiligiga kiritadi; rasmiy tushuntirishda ko‘rib chiqish, qoida tariqasida, 5 ish kuni deb ko‘rsatilgan.","Ijobiy qaror bo‘lsa individual reja va ijtimoiy shartnomani o‘qing; shartlarini bajaring va elektron monitoringni kuzating.","Rad javobi bo‘lsa sababini yozma ko‘ring va rasmiy tartib bo‘yicha tuzatish yoki shikoyat yo‘lini aniqlang."]'::jsonb, '["OneID yoki shaxsni tasdiqlash orqali olinadigan ma’lumotlar.","Ijtimoiy reyestr maqomi yoki daromad mezonini tekshirish uchun portal so‘ragan ma’lumotlar.","Tanlangan yordam turini isbotlovchi hujjat: masalan, kontrakt, kurs shartnomasi, tibbiy xulosa yoki smeta — faqat tegishli tur talab qilsa.","Mahalla/yoshlar yetakchisi yoki rasmiy portal ko‘rsatgan qo‘shimcha tasdiqlar."]'::jsonb, 'Davlat xizmatlari markazi, my.gov.uz yoki Yoshlar yagona elektron platformasi. Ariza doimiy/vaqtincha yashash joyi yoki amalda yashayotgan mahalladagi yoshlar yetakchisiga yo‘naltiriladi.', 'https://my.gov.uz/uz', 'Adliya vazirligi — 2026-yil 25-fevraldagi 78-son qaror bo‘yicha Yoshlar daftari mezonlari', 'https://advice.adliya.uz/oz/news/3010', 'https://advice.adliya.uz/oz/document/2631', 'Yagona umumiy qabul muddati ko‘rsatilmagan. Murojaat yo‘li va aynan tanlangan yordam turining muddatini portal yoki mahallada tekshiring.', '2026-yil 25-fevraldagi 78-son qaror bilan yangilangan: Ijtimoiy reyestr yoki oila a’zosi boshiga daromad mezoni. Yordam individual qaror va ijtimoiy shartnomaga bog‘liq.', '2026-11-07', true, true, 10),
('yoshlar-daftari-kontrakt', '“Yoshlar daftari” — kunduzgi kontraktni qisman qoplash', 'Yoshlar daftari jamg‘armasi · my.gov.uz · mahalla yettiligi', 'education', 'Ijtimoiy reyestrdagi oilalarning 14–30 yoshli a’zolari uchun O‘zbekistondagi ayrim professional ta’lim va OTMlarda kunduzgi kontrakt xarajatining bir qismini qoplash yordami.', 'Kontraktning 50 foizigacha, biroq 50 BHMdan oshmagan qismi qoplanishi mumkin. Pul arizachiga naqd berilmaydi — ma’qullansa ta’lim muassasasiga o‘tkaziladi.', 14, 30, array['Ijtimoiy reyestrga kiritilgan oilaning 14–30 yoshdagi a’zolari','Texnikum, kollej yoki boshqa professional ta’lim tashkilotida kunduzgi kontrakt asosida o‘qiyotganlar','Kunduzgi ta’limda kontrakt asosida o‘qiyotgan davlat yoki nodavlat OTM talabalari']::text[], '{"max_age":30,"min_age":14,"study_mode":"Faqat kunduzgi ta’lim.","benefit_cap":"Kontrakt summasining 50 foizigacha, ammo 50 BHMdan ko‘p emas.","not_eligible":"Ikkinchi va keyingi mutaxassislik; sirtqi, kechki yoki masofaviy ta’lim; qo‘shma ta’lim dasturi; tabaqalashtirilgan (super) kontrakt.","social_register":"Oila Ijtimoiy reyestrga kiritilgan bo‘lishi kerak.","payment_condition":"Ijobiy qarorda mablag‘ ta’lim tashkilotining bank hisobiga o‘tkaziladi; dastlabki oyda ijtimoiy shartnoma shartlari bajarilishi muhim.","application_window":"Rasmiy gender/adliya ma’lumotida murojaatlar iyul–sentabr oylaridan tashqari yil davomida qabul qilinishi aytilgan; portalda joriy xizmatni tekshiring.","eligible_education":"P-Emis tizimidan foydalanadigan professional ta’lim tashkilotlari; HEMIS tizimidagi davlat, nodavlat va O‘zbekistondagi xorijiy OTM filiallari bakalavriat/magistratura."}'::jsonb, '["Yoshingiz 14–30 oralig‘ida va oilangiz Ijtimoiy reyestrda ekanini tekshiring.","O‘qish joyingiz P-Emis yoki HEMIS orqali hisobga olinadigan professional ta’lim/OTM ekanini, ta’lim shakli kunduzgi va kontrakt turi oddiyligini tekshiring.","Sirtqi, kechki, masofaviy, qo‘shma dastur, ikkinchi mutaxassislik yoki super-kontrakt bo‘lsa, bu yordamga mos kelmasligingizni hisobga oling.","my.gov.uz yoki Davlat xizmatlari markazi/Yoshlar yagona elektron platformasida “Yoshlar daftari” kontrakt xarajatini qoplash xizmatini toping.","Portal ko‘rsatgan kontrakt va o‘qish ma’lumotlarini tekshirib arizani yuboring.","Arizani mahalla yettiligi ko‘rib chiqadi; rasmiy ma’lumotda 8 ish kuni keltirilgan. Natijani portalda kuzating.","Ma’qullansa, ta’lim muassasasiga o‘tkaziladigan yordam va ijtimoiy shartnoma majburiyatlarini bajaring."]'::jsonb, '["OneID orqali aniqlanadigan shaxsiy ma’lumotlar.","Kunduzgi ta’lim va kontrakt holati bo‘yicha P-Emis/HEMIS ma’lumotlari.","Amaldagi kontrakt shartnomasi yoki uning raqami — portal so‘rasa.","Ariza portalida talab qilingan qo‘shimcha tasdiqlar."]'::jsonb, 'my.gov.uz, Davlat xizmatlari markazi yoki Yoshlar yagona elektron platformasi orqali yuboriladi; mahalla yettiligi ko‘rib chiqadi.', 'https://my.gov.uz/uz', 'Adliya vazirligi — Yoshlar daftari hisobidan kontraktni qoplash', 'https://gendermadad.adliya.uz/oz/document/2650', 'https://advice.adliya.uz/oz/news/3230', 'Rasmiy tushuntirishda murojaatlar iyul–sentabr oylaridan tashqari yil davomida qabul qilinishi ko‘rsatilgan. Ariza oynasini my.gov.uz da tekshiring.', 'Faqat Ijtimoiy reyestr, 14–30 yosh, kunduzgi shakl va mos ta’lim muassasasi/kontrakt turi shartlariga javob berganda. 50% yoki 50 BHM avtomatik to‘lov emas.', '2026-11-07', true, true, 15),
('2-plus-6', '“2+6” — xorijiy til kursi uchun subsidiya', 'Yoshlar ishlari agentligi', 'language', '14–30 yoshdagi O‘zbekiston fuqarosi yoki rezidenti uchun, belgilangan til va o‘quv markazi shartlariga muvofiq, 8 oylik o‘qishning keyingi 6 oyigacha subsidiya ajratish dasturi.', 'Dastlabki 2 oy o‘qish xarajatini yoshning o‘zi to‘laydi; talablar bajarilsa 3-oydan 6 oygacha davlat subsidiya ajratadi. Rasmiy sahifada xarajatlarning 75 foizigacha tejash ko‘rsatilgan. Davomat kamida 70 foiz bo‘lishi kerak.', 14, 30, array['14–30 yoshdagi O‘zbekiston fuqarosi yoki rezidenti','Ingliz, nemis, fransuz, koreys, xitoy yoki yapon tilini o‘rganmoqchi bo‘lganlar','Til sertifikati bo‘yicha rasmiy sahifadagi talabga javob beradiganlar']::text[], '{"max_age":30,"min_age":14,"important":"Subsidiya o‘quv markaziga, mablag‘ limiti va dastur shartlari doirasida to‘lanadi; yoshning shaxsiy hisobiga erkin pul berilmaydi.","languages":"Ingliz, nemis, fransuz, koreys, xitoy va yapon tillari.","residency":"O‘zbekiston fuqarosi yoki rezidenti bo‘lishi kerak.","attendance":"Kamida 70 foiz davomat. Rasmiy sayt Face ID orqali davomat qaydini ko‘rsatadi.","monthly_caps":"Toshkent shahri — 2 BHMgacha; viloyat markazlari va Qoraqalpog‘iston — 1,5 BHMgacha; tuman/shaharlar — 1 BHMgacha.","first_payment":"Dastlabki 2 oy o‘qish xarajati ariza beruvchi tomonidan to‘lanadi.","previous_subsidy":"FAQ bo‘yicha tanlangan til uchun ilgari subsidiya olmagan bo‘lish kerak.","provider_condition":"Faqat dasturda tasdiqlangan va elektron davomat tizimiga ulangan markaz/filial/kursni tanlash kerak.","certificate_faq_rule":"Shu rasmiy sahifaning batafsil FAQ qismida B2 yoki undan yuqori, 365 kundan eski bo‘lmagan sertifikat talabi ko‘rsatilgan.","official_rule_conflict":"B1 va B2+ talablari ayni rasmiy 2plus6.uz sahifasining turli bo‘limlarida bir-biriga mos kelmaydi. Qaysi mezon aynan arizangizga qo‘llanishini Yonda ilovasidagi tekshiruv yoki rasmiy yordam xizmati orqali aniqlashtirmasdan, dastlabki 2 oylik to‘lovni qilmang.","certificate_summary_rule":"Rasmiy sahifaning asosiy shartlar blokida B1 darajadagi sertifikat yoki unga teng hujjat deb ko‘rsatilgan."}'::jsonb, '["14–30 yosh hamda O‘zbekiston fuqarosi yoki rezidenti bo‘lish shartiga mosligingizni tekshiring.","2plus6.uz sahifasini o‘qing. Eslatma: asosiy blok B1, batafsil FAQ esa B2+ va 365 kun ichidagi sertifikatni aytadi — Yonda yordam xizmati orqali sizga qaysi mezon ishlashini aniqlashtiring.","Tanlangan til bo‘yicha ilgari subsidiya olmaganlik shartini tekshiring.","Tasdiqlangan o‘quv markazi, filial va kursni rasmiy platformadan tanlang; markazning amaldagi maqomini aniqlang.","Yonda ilovasini o‘rnating va OneID orqali kiring.","Til va sertifikat ma’lumotlarini kiriting, 250 so‘zli motivatsion xat yozing, markaz/til/kursni tanlang va raqamli shartnomani diqqat bilan o‘qing.","Faqat sertifikat mezoni va markaz tasdig‘i aniq bo‘lgandan keyin dastlabki 2 oy to‘lovini qiling; kvitansiyani saqlang.","Davomatni kamida 70 foizda ushlang va subsidiya holatini Yonda’da kuzating."]'::jsonb, '["Yonda/OneID orqali aniqlanadigan shaxsiy ma’lumotlar.","Til sertifikati yoki teng hujjat; B1/B2 tafovutini Yonda’da tasdiqlatish shart.","Tanlangan o‘quv markazi, filial va kurs ma’lumotlari.","250 so‘zli motivatsion xat.","Dastlabki 2 oy to‘lovi kvitansiyasi.","Yonda tizimida tasdiqlanadigan raqamli shartnoma."]'::jsonb, 'Ariza Yonda mobil ilovasida OneID orqali beriladi. Avval 2plus6.uz da markaz va talablarni tekshiring. Sertifikat bo‘yicha B1/B2 tafovutini aniqlashtirmasdan to‘lov qilmang. Rasmiy aloqa: +998 55 511 80 88, edu@yoshlar.gov.uz (ish kunlari 09:00–18:00, saytda ko‘rsatilgan).', 'https://2plus6.uz/', 'Yoshlar ishlari agentligi — “2+6” rasmiy platformasi', 'https://2plus6.uz/', 'https://lex.uz/uz/acts/-7759309', 'Rasmiy sayt Yonda orqali ro‘yxatdan o‘tish chaqirig‘ini ko‘rsatadi. Aniq kvota va ayni paytdagi ariza oynasini Yonda ilovasida tekshiring.', 'Muhim: rasmiy 2plus6.uz sahifasida asosiy shartlar blokida B1, batafsil FAQ’da B2+ va 365 kundan eski bo‘lmagan sertifikat deyiladi. Oldingi subsidiya olmaganlik ham FAQ’da ko‘rsatilgan. To‘lovdan oldin yozma tasdiq oling.', '2026-11-07', true, true, 20),
('kelajak-tadbirkori', '“Kelajak tadbirkori” — 15 foizli imtiyozli kredit (2026-yilgi e’lon)', 'Yoshlar tadbirkorligini qo‘llab-quvvatlash tizimi · banklar', 'business', '2026-yil 24-fevraldagi rasmiy e’londa yosh tadbirkorlar uchun 7 yilgacha, 15 foizli kredit yo‘nalishi va biznes bosqichiga qarab limitlar e’lon qilingan.', 'E’lon qilingan limitlar: o‘zini o‘zi band qilganlarga 20 mln so‘mgacha garovsiz; yangi biznes boshlovchilarga 300 mln so‘mgacha; faoliyatini kengaytirishga 2 mlrd so‘mgacha; kamida 5 bitiruvchini ishga olgan tadbirkorlarga 10 mlrd so‘mgacha. Bu kredit, grant emas.', null, null, array['Biznes g‘oyasi yoki amaldagi faoliyati bor yoshlar','O‘zini o‘zi band qilganlar yoki biznesni rivojlantirayotgan tadbirkorlar']::text[], '{"age":"Mazkur e’londa aniq yosh chegarasi ko‘rsatilmagan. Bank va tegishli nizomdan ariza beruvchining yoshi hamda biznes talablari yozma tasdiqlansin.","limits":"20 mln so‘mgacha garovsiz (o‘zini o‘zi band qilganlar); 300 mln so‘mgacha (yangi biznes); 2 mlrd so‘mgacha (faoliyatni kengaytirish); 10 mlrd so‘mgacha (kamida 5 nafar bitiruvchini ishga olgan biznes).","important":"2026-yil 7-noyabr holatida aniq bank mahsuloti, qabul qilayotgan banklar va rasmiy ariza formasi mustaqil tasdiqlanmadi. Limitlar kredit berilishini kafolatlamaydi.","funding_type":"Kredit — foiz va asosiy qarzni qaytarish majburiyati bor. Grant emas.","announced_terms":"2026-yil 24-fevraldagi hukumat e’lonida 7 yilgacha muddat va 15 foiz stavka ko‘rsatilgan."}'::jsonb, '["Faoliyatingiz qaysi toifaga kirishini aniqlang: o‘zini o‘zi band qilish, yangi biznes yoki faoliyatni kengaytirish.","Biznes modeli, real mijoz, daromad-xarajat prognozi va kreditni qaytarish manbasini yozib chiqing.","Kerakli mablag‘ uchun smeta, narx takliflari va loyiha bosqichlarini tayyorlang.","Yoshlar ishlari agentligining hududiy mas’ullari va rasmiy e’lonlarda dasturning amaldagi banki hamda qabul tartibini aniqlang.","Bankdan yozma ravishda yosh talabi, foiz, to‘lov jadvali, ta’minot, imtiyoz davri va talab qilinadigan hujjatlarni oling.","Faqat amaldagi rasmiy bank mahsuloti ochiqligi tasdiqlangandan so‘ng bankning o‘z kanalida ariza yuboring; shartnomani o‘qimasdan imzolamang."]'::jsonb, '["Biznes-reja va daromad-xarajat prognozi — tayyorgarlik hujjati.","Biznes subyekti yoki o‘zini o‘zi band qilish ma’lumoti — tanlangan yo‘nalishga qarab.","Mablag‘ sarfi bo‘yicha smeta, narx takliflari va shartnomalar.","Bank keyinchalik e’lon qiladigan rasmiy hujjatlar ro‘yxati."]'::jsonb, 'Rasmiy e’lon kredit shartlari va limitlarini bildiradi, lekin amaldagi bank ariza formasini ko‘rsatmaydi. Hududiy Yoshlar ishlari agentligi va bankdan joriy qabul kanalini yozma tasdiqlang.', '', 'Hukumat portali — 2026-yil 24-fevraldagi “Kelajak tadbirkori” kredit e’loni', 'https://gov.uz/oz/navoi/news/view/136293', 'https://gov.uz/oz/imv/news/view/154190', 'E’lon 2026-yil 24-fevralda berilgan. 2026-yil 7-noyabr holatida yangi arizalar uchun banklar ro‘yxati va aniq qabul muddati tasdiqlanmadi.', 'Kredit grant emas. 15% va limitlar rasmiy e’londa aytilgan; bankdagi real qabul, yosh mezoni va qo‘shimcha shartlarni tasdiqlamasdan ariza topshirish yoki qarz olish mumkin deb hisoblamang.', '2026-11-07', true, true, 30),
('kelajak-tadbirkori-uzvc', '“Kelajak tadbirkori” — UzVC startap investitsiyasi (2027–2030)', '“UzVC” milliy venchur fondi · PF-175-son Farmon', 'business', '2026-yil 27-avgustdagi PF-175-son Farmon bilan 2027–2030-yillarda 8 ta ustuvor sanoat yo‘nalishida 30 tagacha startapni ochiq tanlov asosida moliyalashtirish belgilangan.', 'Har bir loyihaga 5 mlrd so‘mgacha investitsiya: 3 yilga foizsiz va garovsiz, keyinchalik korxona ulushiga konvertatsiya qilinadigan qarz yoki SAFE shaklida. Bu grant emas; davlat ulushi 49 foizdan oshmasligi va ta’sischilarda bozor narxida sotib olish huquqi nazarda tutilgan.', null, null, array['Startap jamoalari va texnologik/ishlab chiqarish loyihalari','Elektrotexnika, mashinasozlik, farmatsevtika, kimyo, qurilish materiallari, suv/energiya tejamkor texnologiyalar, agrotexnologiya yoki aerokosmos sohasidagi loyihalar']::text[], '{"age":"PF-175 matnining ushbu dastur qismida ariza beruvchi uchun alohida yosh chegarasi ko‘rsatilmagan.","important":"Bu grant yoki oddiy imtiyozli kredit emas — kapitalga konvertatsiya bo‘lishi mumkin bo‘lgan investitsiya instrumenti. Ochiq tanlov sanasi va ariza shakli alohida e’lon qilinishi kerak.","selection":"Farmonda jami 30 tagacha startapni ochiq tanlov asosida moliyalashtirish nazarda tutilgan.","instrument":"3 yilga foizsiz va garovsiz, korxona ulushiga konvertatsiya qilinadigan qarz yoki SAFE.","state_share":"Davlat ulushi 49 foizdan oshirilmaydi; ta’sischilarga davlat ulushini bozor qiymatida sotib olish huquqi beriladi.","program_period":"2027–2030-yillar.","investment_limit":"Har bir loyihaga 5 mlrd so‘mgacha.","priority_sectors":["Elektrotexnika","Mashinasozlik va uskunasozlik","Farmatsevtika","Kimyo sanoati","Qurilish materiallari","Suv va energiya tejovchi texnologiyalar","Qishloq xo‘jaligi va agrotexnologiyalar","Aerokosmos"]}'::jsonb, '["Loyihangiz sakkiz ustuvor yo‘nalishdan qaysi biriga mosligini asoslang.","Muammo, mahsulot, texnologik yangilik, mijoz va bozor hajmini ko‘rsatadigan pitch deck tayyorlang.","MVP/prototip, pilot natijalari, jamoa tajribasi va IP/texnik hujjatlarni tartibga soling.","5 mlrd so‘mgacha talabning har bir qismi uchun xarajat smetasi, bosqich va o‘lchab bo‘ladigan natijalarni yozing.","Investitsiya ulushga konvertatsiya bo‘lishi mumkinligini hisobga olib, cap table, SAFE/konvertatsiya shartlarini yurist va moliyaviy maslahatchi bilan ko‘rib chiqing.","UzVC hamda tegishli rasmiy idoralarning ochiq tanlov e’lonini kuting; e’lon chiqqanda aniq muddat, talab va hujjatlar bilan ariza yuboring."]'::jsonb, '["Pitch deck (tayyorgarlik tavsiyasi; rasmiy tanlov talabi e’lon bilan tasdiqlanadi).","MVP/prototip yoki pilot natijalari.","Jamoa va ta’sischilar haqida qisqa ma’lumot.","Bozor, biznes model, moliyaviy prognoz va xarajatlar smetasi.","IP/texnik hujjatlar — tegishli loyiha uchun.","Rasmiy tanlov e’lon qiladigan ariza va yuridik hujjatlar ro‘yxati."]'::jsonb, 'Hozircha ochiq ariza formasi aniqlanmadi. PF-175-son Farmonni o‘qing va UzVC milliy venchur fondining rasmiy ochiq tanlov e’lonlarini kuzating. Ariza kanali, muddat va hujjatlar tanlov e’lonida tasdiqlanishi kerak.', '', 'Lex.uz — Prezidentning 2026-yil 27-avgustdagi PF-175-son Farmoni', 'https://lex.uz/uz/acts/-8442717', 'https://lex.uz/mact/-8442717', 'Dastur 2027–2030-yillarga mo‘ljallangan. 2026-yil 7-noyabr holatida tanlovning aniq boshlanish sanasi va ariza formasi tasdiqlanmadi.', '“Kelajak tadbirkori” nomidagi 15 foizli bank kreditidan alohida yo‘nalish. Bu grant emas; investitsiya kelgusida ulushga aylanishi mumkin.', '2026-11-07', true, true, 35),
('mening-birinchi-kasbim', '“Mening birinchi kasbim” — bitiruvchilar stajirovkasi', 'Oliy ta’lim, fan va innovatsiyalar vazirligi bilan hamkorlikdagi dastur', 'career', 'Oliy ta’lim muassasasi bitiruvchilari uchun tanlov asosidagi stajirovka va amaliy tajriba yo‘nalishi.', 'Rasmiy e’londa tanlov asosida olingan bitiruvchilarga oyiga 2 mln so‘mgacha stipendiya ko‘zda tutilgani bildirilgan.', null, null, array['Oliy ta’lim muassasasini tamomlagan bitiruvchilar','Tanlov talablariga mos nomzodlar']::text[], '{"stipend":"Rasmiy e’londa oyiga 2 mln so‘mgacha deb ko‘rsatilgan.","audience":"Oliy ta’lim bitiruvchilari; texnikum yoki maktab o‘quvchilari avtomatik ravishda mos hisoblanmaydi.","selection":"Tanlov asosida; amaldagi vakansiya, tashkilot va muddatni rasmiy e’londan tekshirish zarur."}'::jsonb, '["Oliy ta’lim bitiruvchisi sifatida tanlov shartlariga mosligingizni tekshiring.","Yoshlar ishlari agentligi va Oliy ta’lim vazirligining rasmiy e’lonlarida ochiq stajirovka tanlovini qidiring.","CV, diplom ma’lumoti va amaliy ish/portfolio namunalaringizni tayyorlang.","Tanlov e’lonida ko‘rsatilgan rasmiy kanal orqali ariza yuboring.","Suhbat yoki saralash bosqichlariga tayyorlaning; stipendiya va stajirovka shartlarini yozma ravishda tekshiring."]'::jsonb, '["CV/rezyume.","Oliy ta’lim diplomi yoki bitiruvchi ekanlikni tasdiqlovchi ma’lumot.","Portfolio, loyiha yoki amaliy ish namunalari — tanlov talab qilsa.","Tanlov e’lonida so‘ralgan boshqa hujjatlar."]'::jsonb, '2026-yil 24-fevraldagi rasmiy xabarda oliy ta’lim bitiruvchilari uchun tanlovli stajirovka va oyiga 2 mln so‘mgacha stipendiya e’lon qilingan. 2026-yil 7-noyabr holatida amaldagi tanlov sahifasi va ariza formasi tasdiqlanmadi; Yoshlar ishlari agentligi hamda Oliy ta’lim vazirligi e’lonlarini kuzating.', '', 'Hukumat portali — “Mening birinchi kasbim” dasturi haqida rasmiy xabar', 'https://gov.uz/oz/navoi/news/view/136293', '', 'Hozir ochiq tanlov muddati mustaqil tasdiqlanmadi. Rasmiy tanlov e’lon qilinmaguncha bu sahifani amaldagi qabul deb qabul qilmang.', 'E’lon dastur yo‘lga qo‘yilishini bildiradi; hozirgi ochiq vakansiya yoki ariza oynasi tasdiqlanmagan.', '2026-11-07', true, false, 40)
